// Pull tweets out of the raw X GraphQL response(s).
// Only tweets newer than the last run are passed on (stored in workflow static data,
// which persists for active workflows; manual test runs always start fresh).
const state = $getWorkflowStaticData('global');
const lastId = state.lastId ? BigInt(state.lastId) : 0n;
const seen = new Set();
const out = [];

const walk = (v) => {
  if (!v || typeof v !== 'object') return;
  if (Array.isArray(v)) return v.forEach(walk);
  const r = v.tweet_results && v.tweet_results.result;
  if (r) {
    const t = r.tweet || r; // "TweetWithVisibilityResults" wraps the tweet
    if (t.legacy && t.rest_id && !seen.has(t.rest_id)) {
      seen.add(t.rest_id);
      const u = (t.core && t.core.user_results && t.core.user_results.result) || {};
      const username = (u.core && u.core.screen_name) || (u.legacy && u.legacy.screen_name) || '';
      out.push({
        id: t.rest_id,
        createdAt: t.legacy.created_at,
        username,
        text: t.legacy.full_text,
        likes: t.legacy.favorite_count,
        retweets: t.legacy.retweet_count,
        replies: t.legacy.reply_count,
        url: `https://x.com/${username || 'i'}/status/${t.rest_id}`,
      });
    }
  }
  Object.values(v).forEach(walk);
};

for (const item of $input.all()) walk(item.json);

const fresh = out.filter((t) => BigInt(t.id) > lastId);
if (out.length) state.lastId = out.reduce((m, t) => (BigInt(t.id) > BigInt(m) ? t.id : m), state.lastId || '0');
return fresh.map((json) => ({ json }));
